                        agent_message.content_blocks[0].contents.append(
                            TextContent(
                                text=f"Fix Index: {fix_idx}",
                                type="text",
                                header={"title": "Fix Index", "icon": "Tool"},
                                duration=duration_ms,
                            )
                        )
                    if finalizer and finalizer.strip():
